/* eslint-disable space-in-parens */

import AccessorArray = require( '@stdlib/array/base/accessor' );
import ghelmert = require( './index' );


// TESTS //

// The function returns a collection...
{
	const out = new Float64Array( 16 );

	ghelmert( 'row-major', true, 4, out, 4 ); // $ExpectType Float64Array
	ghelmert( 'row-major', true, 4, new AccessorArray( out ), 4 ); // $ExpectType AccessorArray<number>
}

// The compiler throws an error if the function is provided a first argument which is not a valid order...
{
	const out = new Float64Array( 16 );

	ghelmert( 10, true, 4, out, 4 ); // $ExpectError
	ghelmert( true, true, 4, out, 4 ); // $ExpectError
	ghelmert( false, true, 4, out, 4 ); // $ExpectError
	ghelmert( null, true, 4, out, 4 ); // $ExpectError
	ghelmert( undefined, true, 4, out, 4 ); // $ExpectError
	ghelmert( [], true, 4, out, 4 ); // $ExpectError
	ghelmert( {}, true, 4, out, 4 ); // $ExpectError
	ghelmert( ( x: number ): number => x, true, 4, out, 4 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a boolean...
{
	const out = new Float64Array( 16 );

	ghelmert( 'row-major', '10', 4, out, 4 ); // $ExpectError
	ghelmert( 'row-major', 10, 4, out, 4 ); // $ExpectError
	ghelmert( 'row-major', null, 4, out, 4 ); // $ExpectError
	ghelmert( 'row-major', undefined, 4, out, 4 ); // $ExpectError
	ghelmert( 'row-major', [], 4, out, 4 ); // $ExpectError
	ghelmert( 'row-major', {}, 4, out, 4 ); // $ExpectError
	ghelmert( 'row-major', ( x: number ): number => x, 4, out, 4 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	const out = new Float64Array( 16 );

	ghelmert( 'row-major', true, '10', out, 4 ); // $ExpectError
	ghelmert( 'row-major', true, true, out, 4 ); // $ExpectError
	ghelmert( 'row-major', true, false, out, 4 ); // $ExpectError
	ghelmert( 'row-major', true, null, out, 4 ); // $ExpectError
	ghelmert( 'row-major', true, undefined, out, 4 ); // $ExpectError
	ghelmert( 'row-major', true, [], out, 4 ); // $ExpectError
	ghelmert( 'row-major', true, {}, out, 4 ); // $ExpectError
	ghelmert( 'row-major', true, ( x: number ): number => x, out, 4 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a collection...
{
	ghelmert( 'row-major', true, 4, 10, 4 ); // $ExpectError
	ghelmert( 'row-major', true, 4, true, 4 ); // $ExpectError
	ghelmert( 'row-major', true, 4, false, 4 ); // $ExpectError
	ghelmert( 'row-major', true, 4, null, 4 ); // $ExpectError
	ghelmert( 'row-major', true, 4, undefined, 4 ); // $ExpectError
	ghelmert( 'row-major', true, 4, {}, 4 ); // $ExpectError
	ghelmert( 'row-major', true, 4, ( x: number ): number => x, 4 ); // $ExpectError
}

// The compiler throws an error if the function is provided a fifth argument which is not a number...
{
	const out = new Float64Array( 16 );

	ghelmert( 'row-major', true, 4, out, '10' ); // $ExpectError
	ghelmert( 'row-major', true, 4, out, true ); // $ExpectError
	ghelmert( 'row-major', true, 4, out, false ); // $ExpectError
	ghelmert( 'row-major', true, 4, out, null ); // $ExpectError
	ghelmert( 'row-major', true, 4, out, undefined ); // $ExpectError
	ghelmert( 'row-major', true, 4, out, [] ); // $ExpectError
	ghelmert( 'row-major', true, 4, out, {} ); // $ExpectError
	ghelmert( 'row-major', true, 4, out, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const out = new Float64Array( 16 );

	ghelmert(); // $ExpectError
	ghelmert( 'row-major' ); // $ExpectError
	ghelmert( 'row-major', true ); // $ExpectError
	ghelmert( 'row-major', true, 4 ); // $ExpectError
	ghelmert( 'row-major', true, 4, out ); // $ExpectError
	ghelmert( 'row-major', true, 4, out, 4, 10 ); // $ExpectError
}

// Attached to the main export is an `ndarray` method which returns a collection...
{
	const out = new Float64Array( 16 );

	ghelmert.ndarray( true, 4, out, 4, 1, 0 ); // $ExpectType Float64Array
	ghelmert.ndarray( true, 4, new AccessorArray( out ), 4, 1, 0 ); // $ExpectType AccessorArray<number>
}

// The compiler throws an error if the `ndarray` method is provided a first argument which is not a boolean...
{
	const out = new Float64Array( 16 );

	ghelmert.ndarray( '10', 4, out, 4, 1, 0 ); // $ExpectError
	ghelmert.ndarray( 10, 4, out, 4, 1, 0 ); // $ExpectError
	ghelmert.ndarray( null, 4, out, 4, 1, 0 ); // $ExpectError
	ghelmert.ndarray( undefined, 4, out, 4, 1, 0 ); // $ExpectError
	ghelmert.ndarray( [], 4, out, 4, 1, 0 ); // $ExpectError
	ghelmert.ndarray( {}, 4, out, 4, 1, 0 ); // $ExpectError
	ghelmert.ndarray( ( x: number ): number => x, 4, out, 4, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a second argument which is not a number...
{
	const out = new Float64Array( 16 );

	ghelmert.ndarray( true, '10', out, 4, 1, 0 ); // $ExpectError
	ghelmert.ndarray( true, true, out, 4, 1, 0 ); // $ExpectError
	ghelmert.ndarray( true, false, out, 4, 1, 0 ); // $ExpectError
	ghelmert.ndarray( true, null, out, 4, 1, 0 ); // $ExpectError
	ghelmert.ndarray( true, undefined, out, 4, 1, 0 ); // $ExpectError
	ghelmert.ndarray( true, [], out, 4, 1, 0 ); // $ExpectError
	ghelmert.ndarray( true, {}, out, 4, 1, 0 ); // $ExpectError
	ghelmert.ndarray( true, ( x: number ): number => x, out, 4, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a third argument which is not a collection...
{
	ghelmert.ndarray( true, 4, 10, 4, 1, 0 ); // $ExpectError
	ghelmert.ndarray( true, 4, true, 4, 1, 0 ); // $ExpectError
	ghelmert.ndarray( true, 4, false, 4, 1, 0 ); // $ExpectError
	ghelmert.ndarray( true, 4, null, 4, 1, 0 ); // $ExpectError
	ghelmert.ndarray( true, 4, undefined, 4, 1, 0 ); // $ExpectError
	ghelmert.ndarray( true, 4, {}, 4, 1, 0 ); // $ExpectError
	ghelmert.ndarray( true, 4, ( x: number ): number => x, 4, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fourth argument which is not a number...
{
	const out = new Float64Array( 16 );

	ghelmert.ndarray( true, 4, out, '10', 1, 0 ); // $ExpectError
	ghelmert.ndarray( true, 4, out, true, 1, 0 ); // $ExpectError
	ghelmert.ndarray( true, 4, out, false, 1, 0 ); // $ExpectError
	ghelmert.ndarray( true, 4, out, null, 1, 0 ); // $ExpectError
	ghelmert.ndarray( true, 4, out, undefined, 1, 0 ); // $ExpectError
	ghelmert.ndarray( true, 4, out, [], 1, 0 ); // $ExpectError
	ghelmert.ndarray( true, 4, out, {}, 1, 0 ); // $ExpectError
	ghelmert.ndarray( true, 4, out, ( x: number ): number => x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a fifth argument which is not a number...
{
	const out = new Float64Array( 16 );

	ghelmert.ndarray( true, 4, out, 4, '10', 0 ); // $ExpectError
	ghelmert.ndarray( true, 4, out, 4, true, 0 ); // $ExpectError
	ghelmert.ndarray( true, 4, out, 4, false, 0 ); // $ExpectError
	ghelmert.ndarray( true, 4, out, 4, null, 0 ); // $ExpectError
	ghelmert.ndarray( true, 4, out, 4, undefined, 0 ); // $ExpectError
	ghelmert.ndarray( true, 4, out, 4, [], 0 ); // $ExpectError
	ghelmert.ndarray( true, 4, out, 4, {}, 0 ); // $ExpectError
	ghelmert.ndarray( true, 4, out, 4, ( x: number ): number => x, 0 ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided a sixth argument which is not a number...
{
	const out = new Float64Array( 16 );

	ghelmert.ndarray( true, 4, out, 4, 1, '10' ); // $ExpectError
	ghelmert.ndarray( true, 4, out, 4, 1, true ); // $ExpectError
	ghelmert.ndarray( true, 4, out, 4, 1, false ); // $ExpectError
	ghelmert.ndarray( true, 4, out, 4, 1, null ); // $ExpectError
	ghelmert.ndarray( true, 4, out, 4, 1, undefined ); // $ExpectError
	ghelmert.ndarray( true, 4, out, 4, 1, [] ); // $ExpectError
	ghelmert.ndarray( true, 4, out, 4, 1, {} ); // $ExpectError
	ghelmert.ndarray( true, 4, out, 4, 1, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the `ndarray` method is provided an unsupported number of arguments...
{
	const out = new Float64Array( 16 );

	ghelmert.ndarray(); // $ExpectError
	ghelmert.ndarray( true ); // $ExpectError
	ghelmert.ndarray( true, 4 ); // $ExpectError
	ghelmert.ndarray( true, 4, out ); // $ExpectError
	ghelmert.ndarray( true, 4, out, 4 ); // $ExpectError
	ghelmert.ndarray( true, 4, out, 4, 1 ); // $ExpectError
	ghelmert.ndarray( true, 4, out, 4, 1, 0, 10 ); // $ExpectError
}
